package com.aistock.prediction.modelcatalog;
import com.aistock.prediction.forecast.*;import com.aistock.common.BusinessException;
import com.sun.net.httpserver.HttpServer;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.atomic.*;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
class ForecastDependencyTest {
 @Test void missingInputCollectsPublishesAndRechecksFixedVersion()throws Exception{var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);var scopeOp=UUID.randomUUID();var scopeBundle=UUID.randomUUID().toString();var ready=new AtomicBoolean();var seen=new ArrayList<String>();server.createContext("/",e->{assertEquals("private-fixture",e.getRequestHeaders().getFirst("X-Service-Token"));assertEquals("FORECAST",e.getRequestHeaders().getFirst("X-Market-Use-Purpose"));assertEquals(scopeBundle,e.getRequestHeaders().getFirst("X-Market-Use-Bundle"));assertEquals(scopeOp.toString(),e.getRequestHeaders().getFirst("X-Market-Use-Operation"));String path=e.getRequestURI().getPath();seen.add(path);String body;if(path.endsWith("forecast-window")){if(!ready.get()){body="{\"code\":\"FORECAST_INPUT_NOT_AVAILABLE\",\"data\":null}";e.sendResponseHeaders(409,body.length());}else{body="{\"code\":\"OK\",\"data\":"+ForecastMysqlTest.window()+"}";e.sendResponseHeaders(200,body.length());}}else if(path.endsWith("forecast-raw-window")){body="{\"code\":\"OK\",\"data\":{\"state\":\"AVAILABLE\",\"provider\":\"baostock\",\"priceBasis\":\"RAW\",\"versionId\":\"22222222-2222-2222-2222-222222222222\",\"bars\":[{\"date\":\"2026-07-01\"},{\"date\":\"2026-09-30\"}]}}";e.sendResponseHeaders(200,body.length());}else if(path.endsWith("forecast-collect")){body="{\"state\":\"AVAILABLE\",\"candidate\":{\"fixture\":true}}";e.sendResponseHeaders(200,body.length());}else{ready.set(true);body="{\"code\":\"OK\",\"data\":{\"inputVersionId\":\"11111111-1111-1111-1111-111111111111\"}}";e.sendResponseHeaders(200,body.length());}e.getResponseBody().write(body.getBytes(StandardCharsets.UTF_8));e.close();});server.start();try(var scope=com.aistock.prediction.marketuse.MarketUseContext.open(new com.aistock.prediction.marketuse.MarketUseClient.Request(scopeOp.toString(),"1",UUID.randomUUID().toString(),"FORECAST",new com.aistock.common.marketlifecycle.MarketUseRecords.Selector("CURRENT_HEADS",null,null,List.of("SH600030"))),new com.aistock.prediction.marketuse.MarketUseClient.Receipt(scopeBundle,"ACTIVE",List.of("22222222-2222-2222-2222-222222222222")))){String url="http://127.0.0.1:"+server.getAddress().getPort();var d=new HttpForecastDependencies(url,url,"private-fixture",ForecastMysqlTest.M);assertEquals("FRESH",d.prepare("SH600030",scopeOp).path("freshness").asText());assertTrue(seen.contains("/internal/v1/market/forecast-collect"));assertTrue(seen.contains("/internal/v1/market/forecast-inputs"));}finally{server.stop(0);}}
 @Test void unavailableRawVersionPreservesSafeReasonWithoutCallingCollector()throws Exception{
  var calls=new AtomicInteger();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);
  server.createContext("/",e->{calls.incrementAndGet();String body="{\"code\":\"MARKET_VERSION_UNAVAILABLE\",\"message\":\"private fixture\",\"data\":null}";e.sendResponseHeaders(422,body.length());e.getResponseBody().write(body.getBytes(StandardCharsets.UTF_8));e.close();});server.start();
  try{String url="http://127.0.0.1:"+server.getAddress().getPort();var d=new HttpForecastDependencies(url,url,"private-fixture",ForecastMysqlTest.M);var error=assertThrows(BusinessException.class,()->d.prepare("SH600030",UUID.randomUUID()));assertEquals("MARKET_VERSION_UNAVAILABLE",error.code());assertFalse(error.getMessage().contains("private fixture"));assertEquals(1,calls.get());}finally{server.stop(0);}
 }
 @Test void redirectsAndOversizeFailClosedWithoutRetryOrSecretMessage()throws Exception{for(boolean large:List.of(false,true)){var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",e->{if(large){var bytes=new byte[131073];e.sendResponseHeaders(200,bytes.length);e.getResponseBody().write(bytes);}else{e.getResponseHeaders().set("Location","http://127.0.0.1:1/leak");e.sendResponseHeaders(302,-1);}e.close();});server.start();try{var d=new HttpForecastDependencies("http://127.0.0.1:"+server.getAddress().getPort(),"http://127.0.0.1:1","private-fixture",ForecastMysqlTest.M);var error=assertThrows(BusinessException.class,()->d.prepare("SH600030",UUID.randomUUID()));assertFalse(error.getMessage().contains("private-fixture"));}finally{server.stop(0);}}}
 @Test void publishedFixtureInferenceSendsOnlyFixedIdentities()throws Exception{var v=new ModelRecords.Version(UUID.fromString("33333333-3333-3333-3333-333333333333"),"fixture","a".repeat(64),"c".repeat(64),"PUBLISHED",1,true,"e".repeat(64),ModelCatalogMysqlTest.manifest("fixture"),ModelCatalogMysqlTest.candidate(42).evaluation(),ForecastMysqlTest.NOW);var seen=new AtomicReference<com.fasterxml.jackson.databind.JsonNode>();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/internal/v1/infer",e->{seen.set(ForecastMysqlTest.M.readTree(e.getRequestBody().readAllBytes()));String body="{\"state\":\"AVAILABLE\",\"result\":"+ForecastMysqlTest.result(v,ForecastMysqlTest.window())+"}";byte[] bytes=body.getBytes(StandardCharsets.UTF_8);e.sendResponseHeaders(200,bytes.length);e.getResponseBody().write(bytes);e.close();});server.start();try{var d=new HttpForecastDependencies("http://127.0.0.1:1","http://127.0.0.1:"+server.getAddress().getPort(),"private-fixture",ForecastMysqlTest.M);assertEquals(5,d.infer(v,ForecastMysqlTest.window()).path("points").size());var names=new HashSet<String>();seen.get().fieldNames().forEachRemaining(names::add);assertEquals(Set.of("modelId","artifactId","manifestHash","instrumentId","inputVersionId"),names);}finally{server.stop(0);}}
 @Test void stalledResponseBodyIsBoundedByWholeDeadline()throws Exception{var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",e->{e.sendResponseHeaders(200,100);try{Thread.sleep(15000);}catch(InterruptedException interrupted){Thread.currentThread().interrupt();}finally{e.close();}});server.start();try{var d=new HttpForecastDependencies("http://127.0.0.1:"+server.getAddress().getPort(),"http://127.0.0.1:1","private-fixture",ForecastMysqlTest.M);long started=System.nanoTime();assertThrows(BusinessException.class,()->d.prepare("SH600030",UUID.randomUUID()));assertTrue((System.nanoTime()-started)/1e9<14);}finally{server.stop(0);}}
 @Test void preparationChecksOwnerBeforeStartingCollection() throws Exception {
  var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);
  var seen=new java.util.concurrent.CopyOnWriteArrayList<String>();
  var expired=new AtomicBoolean();
  server.createContext("/",e->{
   var path=e.getRequestURI().getPath();
   seen.add(path);
   boolean raw=path.endsWith("forecast-raw-window");
   String body=raw?"{\"code\":\"OK\",\"data\":{\"state\":\"AVAILABLE\",\"provider\":\"baostock\",\"priceBasis\":\"RAW\",\"versionId\":\"22222222-2222-2222-2222-222222222222\",\"bars\":[{\"date\":\"2026-09-30\"}]}}":"{\"code\":\"FORECAST_INPUT_NOT_AVAILABLE\",\"data\":null}";
   if(raw)expired.set(true);
   byte[] bytes=body.getBytes(StandardCharsets.UTF_8);
   e.sendResponseHeaders(raw?200:409,bytes.length);e.getResponseBody().write(bytes);e.close();
  });
  server.start();
  try{
   var url="http://127.0.0.1:"+server.getAddress().getPort();
   var d=new HttpForecastDependencies(url,url,"private-fixture",ForecastMysqlTest.M,op->{if(expired.get())throw com.aistock.prediction.marketuse.MarketUseClient.unavailable();});
   assertThrows(com.aistock.common.BusinessException.class,()->d.prepare("SH600030",UUID.randomUUID()));
   assertEquals(List.of("/internal/v1/market/forecast-window","/internal/v1/market/forecast-raw-window"),seen);
  }finally{server.stop(0);}
 }

}
